fun oneLoop(n: Int): Int {
    var steps = 0
    for (i in 1..n) {
        steps++
    }
    return steps
}

fun twoLoops(n: Int): Int {
    var steps = 0
    for (i in 1..n) {
        for (j in 1..n) {
            steps++
        }
    }
    return steps
}

fun main() {
    for (n in listOf(10, 100, 1000)) {
        println("n = $n: one loop ${oneLoop(n)}, two loops ${twoLoops(n)}")
    }
}

